import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { TRIVIA_NICKNAME_POLICY as policy } from '../src/lib/trivia-nickname.ts';

const quote = (value) => `'${value.replaceAll("'", "''")}'`;
const start = '-- BEGIN GENERATED TRIVIA NICKNAME POLICY';
const end = '-- END GENERATED TRIVIA NICKNAME POLICY';
export const generatedPolicy = `${start}
-- Generated by scripts/sync-trivia-nickname-policy.mjs; edit src/lib/trivia-nickname.ts.
create or replace function public.is_trivia_nickname_allowed(p_name text)
returns boolean language plpgsql immutable set search_path = '' as $$
declare
 folded text := lower(normalize(coalesce(p_name, ''), NFKD));
 candidate text;
 compact text;
 collapsed text;
begin
 folded := regexp_replace(folded, U&'[\\0300-\\036f]', '', 'g');
 foreach candidate in array array[folded, translate(folded, ${quote(policy.from)}, ${quote(policy.to)})] loop
  compact := regexp_replace(candidate, '[^a-z0-9]', '', 'g');
  compact := regexp_replace(compact, '^[0-9x]+|[0-9x]+$', '', 'g');
  collapsed := regexp_replace(compact, '([a-z])\\1+', '\\1', 'g');
  if compact ~ ${quote(policy.strong)} or collapsed ~ ${quote(policy.strong)}
   or candidate ~ ${quote(`(^|[^a-z])(${policy.word})([^a-z]|$)`)}
   or compact ~ ${quote(`^(${policy.prefix})*(${policy.word})(${policy.suffix})*$`)}
   or collapsed ~ ${quote(`^(${policy.prefix})*(${policy.word})(${policy.suffix})*$`)} then return false; end if;
 end loop;
 return true;
end;
$$;
${end}`;

export function syncPolicy(check = false) {
	const path = fileURLToPath(new URL('../supabase/sql/trivia_high_scores.sql', import.meta.url));
	const source = readFileSync(path, 'utf8').replace(/\r\n/g, '\n');
	const first = source.indexOf(start);
	const last = source.indexOf(end);
	const next = first >= 0 && last >= first
		? source.slice(0, first) + generatedPolicy + source.slice(last + end.length)
		: source.replace(/begin;\r?\n/, `begin;\n${generatedPolicy}\n`);
	if (check && next !== source) throw new Error('Política SQL desactualizada. Ejecutá node --experimental-strip-types scripts/sync-trivia-nickname-policy.mjs');
	if (!check) writeFileSync(path, next);
}

if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) syncPolicy(process.argv.includes('--check'));
